import {expect, test} from '@playwright/test';

const englishSentences = [
	'We are very delighted that you have shown interest in our enterprise',
	'Personal data means any information relating to an identified or identifiable natural person',
	'Each data subject shall have the right granted by the European legislator',
	'As a responsible company, we do not use automatic decision-making or profiling.',
	'This Privacy Policy has been generated by the Privacy Policy Generator',
	'Phone:',
	'Email:',
];

const expectNoEnglish = page => Promise.all(englishSentences.map(sentence => expect(page.locator('main')).not.toContainText(sentence, {useInnerText: true})));

test.describe('imprint in German', () => {
	test('switching the language translates headings, address, policy text and titles', async ({page}) => {
		await page.goto('/imprint/');
		await expect(page.locator('main h1')).toHaveText(/^contact & imprint$/iv, {useInnerText: true});
		await expect(page.getByText('We are very delighted').first()).toBeVisible();

		await page.locator('[data-language-switcher]').click();
		await expect(page.locator('html')).toHaveAttribute('lang', 'de');

		await expect(page.locator('main h1')).toHaveText(/^kontakt & impressum$/iv, {useInnerText: true});
		await expect(page.locator('#privacy-policy')).toHaveText('Datenschutzerklärung', {useInnerText: true});
		await expect(page.locator('main h3').first()).toHaveText('1. Begriffsbestimmungen', {useInnerText: true});
		await expect(page.getByText('Wir freuen uns sehr über Ihr Interesse').first()).toBeVisible();
		await expect(page.getByText('Personenbezogene Daten sind alle Informationen').first()).toBeVisible();
		await expect(page.locator('address')).toContainText('Telefon: 84183026');
		await expect(page.locator('address')).toContainText('Deutschland');
		await expect(page.locator('address')).toContainText('Friedrich-Wilhelm-Platz 2');
		await expect(page.locator('i.icon-cc-nc-eu')).toHaveAttribute('title', /^Nicht kommerziell/v);

		await expectNoEnglish(page);

		await page.locator('[data-language-switcher]').click();
		await expect(page.locator('i.icon-cc-nc-eu')).toHaveAttribute('title', /^NonCommercial/v);
		await expect(page.getByText('Personal data means any information').first()).toBeVisible();
	});

	test('a stored German choice is applied on load without English policy text', async ({page}) => {
		await page.addInitScript(() => {
			localStorage.setItem('userLanguage', 'de');
		});
		await page.goto('/imprint/');
		await expect(page.locator('html')).toHaveAttribute('lang', 'de');
		await expectNoEnglish(page);

		await expect(page.locator('main h1')).toHaveText(/^kontakt & impressum$/iv, {useInnerText: true});
	});
});
